/*!40000 ALTER TABLE `services` DISABLE KEYS */;
INSERT INTO `services` VALUES (1,'General / Basic Service','Engine oil top-up/change, air filter clean, 21-point vehicle health check, exterior foam wash, and tire pressure check.','90 Mins',1,'2026-08-14 10:36:45'),(2,'Standard Periodic Service','Engine oil & oil filter replacement, air & fuel filter cleaning, brake pads cleaning, coolant top-up, spark plug check, and complete 40-point inspection.','3 - 4 Hours',1,'2026-08-14 10:36:45'),(3,'Comprehensive / Major Service','Complete fluids flush (engine oil, brake fluid, coolant), throttle body clean, brake disc & caliper service, wheel balancing/alignment check, and 60-point full body diagnostic.','5 - 6 Hours',1,'2026-08-14 10:36:45'),(4,'Doorstep Breakdown & Jumpstart','On-spot battery jumpstart, fuse check, starter motor inspection, or fuel delivery support for dead vehicles.','30 - 45 Mins',1,'2026-08-14 10:36:45'),(5,'Flat Tyre & Puncture Assistance','Tubeless puncture repair, doorstep spare wheel swap, and digital tyre pressure calibration.','30 Mins',1,'2026-08-14 10:36:45'),(6,'AC Deep Disinfection & Gas Top-Up','AC gas refrigerant refill (R134a/R1234yf), cabin pollen filter replacement, cooling coil visual check, and antibacterial vent duct cleaning.','2 Hours',1,'2026-08-14 10:36:45'),(7,'Brake & Clutch Overhaul','Front/rear brake pad replacement, rotor skimming inspection, clutch cable/wire adjustment, and brake bleeding.','2 - 3 Hours',1,'2026-08-14 10:36:45'),(8,'EV Battery & Motor Health Diagnostic','High-voltage battery State-of-Health (SoH) diagnostics, BMS system firmware scan, thermal cooling check, and motor insulation test.','2 Hours',1,'2026-08-14 10:36:45'),(9,'Chain Clean & Drivetrain Lubrication','Two-wheeler chain degreasing, roller inspection, tension adjustment, and high-temp synthetic chain lube application.','45 Mins',1,'2026-08-14 10:36:45'),(10,'Deep Interior & Exterior Spa','Interior vacuuming, fabric shampooing, roof dry-cleaning, dashboard polish, underbody wash, and exterior wax polish.','3 - 4 Hours',1,'2026-08-14 10:36:45'),(11,'Ceramic Coating & Paint Shield','Dual-layer 9H ceramic coating, clay bar paint decontamination, light scratch swirl removal, and ultra-hydrophobic coating.','1 - 2 Days',1,'2026-08-14 10:36:45');
/*!40000 ALTER TABLE `services` ENABLE KEYS */;
UNLOCK TABLES;

