INSERT INTO `site_settings` VALUES ('about_badge','About Us','about','2026-09-26 10:52:39'),('about_story_p1','At HR Auto Mobile, we recognized the challenges vehicle owners face when searching for reliable and affordable car and bike services. Many customers struggle to find trustworthy workshops, transparent pricing, and convenient booking options. We created this platform to bridge that gap and make vehicle maintenance more accessible for everyone.','about','2026-09-26 10:52:39'),('about_story_p2','Our vision is to simplify the automotive service experience through technology. Instead of spending hours searching for service centers or comparing options, customers can quickly find the right services, book appointments, and manage their vehicle maintenance needs from a single platform.','about','2026-09-26 10:52:39'),('about_story_title','Why We Built HR Auto Mobile','about','2026-09-26 10:52:39'),('about_subtitle','Bike and car repair across 32+ Indian cities — trusted by 20,000+ customers','about','2026-09-26 10:52:39'),('about_title','Making Vehicle Service Hassle-Free','about','2026-09-26 10:52:39'),('business_hours','Mon - Sat: 9:00 AM - 8:00 PM (Sunday Open)','contact','2026-09-26 10:52:39'),('contact_address','Housing board, Ambedkarnagar, Surendranagar, Gujarat 363001','contact','2026-09-26 10:52:39'),('contact_email','hrautomobile@gmail.com','contact','2026-09-26 10:52:39'),('contact_phone','+91 9016747304','contact','2026-09-26 10:52:39'),('cta_btn_link','services.php','cta','2026-09-26 10:52:39'),('cta_btn_text','Book Now','cta','2026-09-26 10:52:39'),('cta_desc','Book your next car or bike service with HR Auto Mobile and enjoy a smooth, reliable experience!','cta','2026-09-26 10:52:39'),('cta_title','Ready to Experience Hassle-Free Maintenance?','cta','2026-09-26 10:52:39'),('google_map_embed','','contact','2026-08-29 16:07:00'),('hero_btn_link','services.php','hero','2026-09-26 10:52:39'),('hero_btn_text','Book Now','hero','2026-09-26 10:52:39'),('hero